class Channel:
    def __init__(self, name):
        self.name = name

    def __str__(self):
        return f"Channel: {self.name}"

c = Channel("Meta")
print(c)

class Campaign:
    def __init__(self, name):
        self.name = name

    def label(self):
        return self.name.upper()


class EmailCampaign(Campaign):
    def label(self):
        return "EMAIL " + super().label()


c = EmailCampaign("promo")
print(c.label())

