class Product {
  constructor(name, price) {
    this.name = name;
    this.price = price;
  }
  label() {
    return `${this.name} ${this.price} EUR`;
  }
}
class Ebook extends Product {
  label() {
    return super.label() + " (PDF)";
  }
}
console.log(new Ebook("Guide GEO", 29).label());

